#include <iostream>
#include <iomanip>

int main() {
    // Đọc số nguyên giữa 0 và 1000 và tính tổng chữ số (Bài 2.6)
    int number = 0;
    if (std::cin >> number) {
        int d1 = number % 10;         // chữ số hàng đơn vị
        int remaining = number / 10;
        int d2 = remaining % 10;      // chữ số hàng chục
        int d3 = remaining / 10;      // chữ số hàng trăm
        int sum = d1 + d2 + d3;
        std::cout << "The sum of the digits is " << sum << "\n";
    }
    return 0;
}

#include <iostream>
#include <cmath>
#include <iomanip>

int main() {
    // Đọc tọa độ hai điểm (x1, y1) và (x2, y2) và tính khoảng cách (Bài 2.15)
    double x1 = 0.0, y1 = 0.0, x2 = 0.0, y2 = 0.0;
    if (std::cin >> x1 >> y1 >> x2 >> y2) {
        double distance = std::sqrt(std::pow(x2 - x1, 2) + std::pow(y2 - y1, 2));
        std::cout << std::setprecision(16) << "The distance between the two points is " << distance << "\n";
    }
    return 0;
}
